use axum::{Router,routing::get,response::Html,Json};use std::{fs,path::PathBuf,sync::Mutex};static LOCK:Mutex<()>=Mutex::new(());
fn value(add:bool)->i64 {let _g=LOCK.lock().unwrap();let p=PathBuf::from(std::env::var("PODS_APP_DATA").unwrap_or("/data".into())).join("count");let mut n=fs::read_to_string(&p).unwrap_or_default().parse::<i64>().unwrap_or(0);if add{n+=1;fs::write(p,n.to_string()).unwrap();}n}
async fn home()->Html<&'static str>{Html(r##"<!doctype html><html><title>Axum counter</title><h1>Axum counter</h1><p id="value"></p><button id="add">Add one</button><script>async function refresh(){document.querySelector("#value").textContent=(await(await fetch("/api/count")).json()).count}document.querySelector("#add").onclick=async()=>{await fetch("/api/count",{method:"POST"});refresh()};refresh()</script></html>"##)}
async fn read()->Json<serde_json::Value>{Json(serde_json::json!({"count":value(false)}))}async fn add()->Json<serde_json::Value>{Json(serde_json::json!({"count":value(true)}))}
#[tokio::main]async fn main(){let app=Router::new().route("/",get(home)).route("/api/count",get(read).post(add));let listener=tokio::net::TcpListener::bind("0.0.0.0:8080").await.unwrap();axum::serve(listener,app).await.unwrap();}
